    const urls = { asset: assetA, depreciationRun: depA, budget: `/budgets/${ctx.budgetV2}`, payrollRun: `/payroll/runs/${ctx.payrollRunA ?? ''}`, financialAccountEdit: `/financial-accounts/${ctx.financial['UAT Cash A']}/edit`, movementsA: `/inventory/movements?branch_id=${ctx.branchA}` };
    await go(acc, '/payroll/runs');
