    statuses.adjustmentApprove = bb.documentStatus;
    await go(bb, '/dashboard');
    await act(bb, (id) => crafted(`/financial-accounts/${id}/toggle`), ctx.financial['UAT Cash A']);
    statuses.financialAccountToggle = bb.documentStatus;
    c.evidence.branchB = { ...statuses, movementRowsOfBranchA: movementRows };
    for (const name of ['asset', 'depreciationRun', 'budget', 'payrollRun', 'financialAccountEdit', 'adjustmentApprove', 'financialAccountToggle']) {
        check(c, `Branch-B user refused: ${name}`, [403, 404].includes(statuses[name]), statuses[name]);
    }
    check(c, 'Branch-B user: movement history filtered to Branch A shows no Branch-A rows (or is refused)', [403, 404].includes(statuses.movementsA) || movementRows === 0, { status: statuses.movementsA, rows: movementRows });
    const apr = await as('approver');
    await go(apr, '/inventory/adjustments');
    if (adjA) await act(apr, (id) => { const tr = $$('.app-content table tbody tr').find((r) => txt(r).includes('#' + id)); const f = $('form[action*="/reject"]', tr); fill(f, { reason: 'UAT release: probe only' }); submitForm(f, 'Reject'); }, adjA);

    step(c, 'Cashier creates and submits petty cash 500.00; cannot approve it');
