    if (pc.id) await clickTx(cashier, 'Submit for approval');
    const cs = await txState(cashier);
    await act(cashier, (id) => crafted(`/finance/transaction/${id}/approve`), pc.id);
    const cashierApprove = cashier.documentStatus;
    await go(cashier, `/finance/transaction/${pc.id}`);
    const after = await txState(cashier);
