await runCase(newCase('RC-11', 'Exports (CSV, XLSX, PDF) through the on-screen links', 'Each report offers CSV/Excel/PDF; each download 200 with the right content type and signature (%PDF, PK).'), async (c) => {
    const acc = await as('accountant');
    const targets = [
        ['general-ledger', `/reports/general-ledger?fiscal_year_id=${ctx.fy2026}&account_id=${ctx.account['11101']}&from=2026-01-01&to=2026-12-31`],
        ['balance-sheet', '/statements/balance-sheet'],
        ['income-expenditure', '/statements/income-expenditure'],
        ['cash-flow', `/reports/cash-flow?fiscal_year_id=${ctx.fy2026}&branch_id=${ctx.branchA}`],
        ['receipts-payments', `/reports/receipts-payments?fiscal_year_id=${ctx.fy2026}&branch_id=${ctx.branchA}`],
        ['payables-aging', '/reports/payables'],
        ['budget-vs-actual', ctx.bvaUrl ?? `/budget-reports/versus-actual?fiscal_year_id=${ctx.fy2026}&branch_id=${ctx.branchA}`],
        ['asset-register', `/reports/assets/register?branch_id=${ctx.branchB}&as_of=2026-12-31`],
        ['inventory-stock', '/reports/inventory/stock-balance'],
        ['payroll-register', `/payroll-reports/register?run_id=${ctx.payrollRunB}`],
        ['frc-reconciliation', '/frc-integration/reconciliation'],
    ];
    c.evidence.exports = {};
    for (const [report, path] of targets) {
      try {
        const st = await go(acc, path);
        const links = await ev(acc, () => exportLinks());
        const pageAlerts = (await info(acc)).alerts;
        check(c, `${report}: page 200 with CSV, Excel and PDF links`, st === 200 && ['csv', 'xlsx', 'pdf'].every((f) => links.some((h) => new RegExp(`/export/${f}(\\?|$)`).test(h))), { status: st, links: links.map((h) => h.replace(BASE, '')), alerts: pageAlerts.slice(0, 2) });
        for (const href of links) {
            const format = href.match(/\/export\/(csv|xlsx|pdf)/)?.[1];
            const r = await download(acc, href);
            const ok = r.status === 200 && (format === 'pdf' ? r.head.startsWith('%PDF') && /pdf/.test(r.type) : format === 'xlsx' ? r.head.startsWith('PK') && /spreadsheet|excel|octet/.test(r.type) : /csv|text/.test(r.type) && (r.text ?? '').length > 20);
            c.evidence.exports[`${report}.${format}`] = { status: r.status, type: r.type, size: r.size, head: r.head.replace(/[^\x20-\x7e]/g, '.') };
            check(c, `${report}.${format}: 200 + content type + signature`, ok, c.evidence.exports[`${report}.${format}`]);
        }
      } catch (error) {
        check(c, `${report}: page could be opened`, false, String(error).slice(0, 200));
      }
    }
});

