// =============================================================== RC-13 Year-end closing
await runCase(newCase('RC-13', 'Year-end closing FY 2026 and FY 2027 carry-forward', 'Preview lists income/expense per branch; closing posted with a reason; I&E net zero after closing; Balance Sheet carries the surplus in 31102; FY 2027 created and its Trial Balance carries balance-sheet balances.'), async (c) => {
    const admin = await as('admin');
    const indexStatus = await go(admin, '/fiscal-years');
    const indexInfo = await info(admin);
    c.evidence.fiscalYearsIndex = { status: indexStatus, serverError: indexInfo.serverError };
    check(c, 'Fiscal Years list opens (200)', indexStatus === 200 && !indexInfo.serverError, c.evidence.fiscalYearsIndex);
    if (indexStatus >= 500) defect(c, { page: '/fiscal-years', steps: 'Log in as uat.admin and open Accounting Setup → Fiscal Years', expected: 'Fiscal year list (200)', actual: `HTTP ${indexStatus} server error`, evidence: 'storage/logs/laravel.log: ViewException "syntax error, unexpected token endforeach" in resources/views/accounting-setup/fiscal-years/index.blade.php (observed while the year-end closing feature was being edited)' });
    let fyLink = indexStatus === 200 ? await ev(admin, () => $$('.app-content a').map((a) => ({ text: txt(a.closest('tr') ?? a), href: a.getAttribute('href') })).find((x) => /FY 2026/.test(x.text) && /fiscal-years\/\d+$/.test(x.href ?? ''))?.href) : null;
    fyLink ??= `/fiscal-years/${ctx.fy2026}`;
    await go(admin, fyLink);
    const closingLink = await ev(admin, () => $$('a').find((a) => /Year-end closing/.test(txt(a)))?.getAttribute('href'));
    c.evidence.feature = { fiscalYear: fyLink, closingLink };
    if (!closingLink) {
        c.status = 'NOT RUN';
        c.actual = 'Year-end closing feature not present (no "Year-end closing" link on the FY 2026 page).';
        return;
    }
    step(c, 'Admin opens Year-end closing preview for FY 2026');
    const st = await go(admin, closingLink);
    const preview = await ev(admin, () => ({ blockers: $$('.alert-warning li').map(txt), surplusLedger: txt($('.card-copy')), branches: $$('h3.section-title').map((h) => { const table = h.nextElementSibling?.querySelector('table'); return { branch: txt(h), lines: table ? rows($('tbody', table)).map((r) => r.slice(0, 3).join(' | ')) : [], totals: table ? rows($('tfoot', table)).map((r) => r.join(' ')) : [] }; }), totals: rows($$('.app-content table').at(-2) ?? document).map((r) => r.join(' ')), canPost: !!formByAction('/closing$') }));
    c.evidence.preview = preview;
    c.evidence.previewScreenshot = await shot(admin, 'rc-13-closing-preview');
    check(c, 'Preview 200 lists income and expense ledgers per branch (A and B) and the 31102 surplus ledger', st === 200 && preview.branches.length >= 2 && preview.branches.every((b) => b.lines.length > 0) && /31102/.test(preview.surplusLedger) && preview.branches.some((b) => b.lines.some((l) => /^4/.test(l))) && preview.branches.some((b) => b.lines.some((l) => /^5/.test(l))), preview);
    if (preview.blockers.some((b) => /still draft, submitted or approved/.test(b))) {
        step(c, 'Blocker: unposted FY 2026 journals. Clear them through the UI (a draft cannot be rejected, so it is corrected, submitted and returned by the approver)');
        const acc = await as('accountant');
        const apr = await as('approver');
        const pending = [];
        for (const status of ['draft', 'submitted', 'approved']) {
            await go(acc, `/journals?status=${status}`);
            pending.push(...await ev(acc, () => $$('.app-content table tbody tr').map((tr) => tr.querySelector('a[href*="/journals/"]')?.getAttribute('href')).filter(Boolean)));
        }
        c.evidence.unpostedJournals = pending;
        for (const href of pending) {
            await go(acc, href);
            const j = await journalState(acc);
            if (/Draft/.test(j.desc)) {
                // A draft that can never be submitted (cash guard) is discarded with a reason through the UI.
                const canDiscard = await ev(acc, () => !!formByAction('/journals/\\d+$'));
                check(c, `Draft ${href} offers Discard Draft`, canDiscard, href);
                if (!canDiscard) {
                    defect(c, { page: href, steps: 'Open a draft manual journal that the cash guard refuses to submit', expected: 'A Discard Draft action', actual: 'No discard action, so the draft blocks the year-end closing', evidence: (await journalState(acc)).desc });
                    continue;
                }
                await act(acc, () => { const f = formByAction('/journals/\\d+$'); fill(f, { reason: 'UAT release: draft refused by the cash guard, discarded before closing' }); submitForm(f, 'Discard Draft'); });
                c.evidence[`discarded ${href}`] = (await info(acc)).alerts;
                continue;
            }
            await go(apr, href);
            if (await ev(apr, () => !!formByAction('/reject$'))) await act(apr, () => { const f = formByAction('/reject$'); fill(f, { reason: 'UAT release: returned before year-end closing' }); submitForm(f, 'Return'); });
            await go(acc, href);
            c.evidence[`cleared ${href}`] = (await journalState(acc)).desc;
        }
        await go(admin, closingLink);
        Object.assign(preview, await ev(admin, () => ({ blockers: $$('.alert-warning li').map(txt), canPost: !!formByAction('/closing$') })));
        c.evidence.blockersAfterClearing = preview.blockers;
    }
    const unfinished = results.cases.filter((x) => x.id !== 'RC-13' && !['PASS', 'FAIL'].includes(x.status)).map((x) => x.id);
    if (unfinished.length) { note(c, `Closing not posted: cases not finished: ${unfinished.join(', ')}`); check(c, 'All other cases finished before posting the closing', false, unfinished); return; }
    if (!preview.canPost) { check(c, 'Closing can be posted (no blockers)', false, preview.blockers); return; }

    step(c, 'Post the closing entries with a reason (confirm accepted)');
    await act(admin, () => { const f = formByAction('/closing$'); fill(f, { reason: 'UAT release: synthetic annual closing approved for testing' }); submitForm(f, 'Post closing entries'); });
    const after = await ev(admin, () => ({ alerts: $$('.alert').map(txt), journals: rows($$('.app-content table').at(-1)).slice(1).map((r) => ({ voucher: r[0], branch: r[1], date: r[2], amount: r[3], status: r[4] })), links: $$('.app-content table').at(-1) ? $$('a', $$('.app-content table').at(-1)).map((a) => a.getAttribute('href')) : [] }));
    c.evidence.posted = after;
    check(c, 'Closing journals posted for both branches (JV, 31 Dec 2026)', after.journals.length >= 2 && after.journals.every((j) => /Posted/i.test(j.status) && /31 Dec 2026/.test(j.date)), after);
    if (after.links[0]) {
        await go(admin, after.links[0]);
        const j = await journalState(admin);
        c.evidence.closingJournal = { title: j.title, desc: j.desc, lines: j.lines.slice(0, 12) };
        check(c, 'Closing journal touches only income/expense ledgers and 31102', j.lines.length > 1 && j.lines.every((l) => /^(4|5)\d{4}|^31102/.test(l[1])), c.evidence.closingJournal);
    }
    const acc = await as('accountant');
    const ie = await statement(acc, '/statements/income-expenditure');
    c.evidence.incomeExpenditure = ie.rows.filter((r) => /Total|Surplus|Deficit/.test(r[0]));
    const net = ie.rows.find((r) => /Surplus|Deficit/i.test(r[0]))?.[1];
    const surplusPreview = money(preview.totals.find((r) => /Net surplus/.test(r))?.replace(/Net surplus\/\(deficit\)/, ''));
    // By documented design (IncomeExpenditureStatement::METHOD) year-end closing journals are excluded from I&E, so a closed
    // year still shows its result; the zeroing is verified on the closing page and the Balance Sheet instead.
    note(c, 'I&E excludes year-end closing journals by documented design ("a closed year still shows its income and expenditure"); zero remaining I&E balance is verified on the closing page and the carry to 31102 on the Balance Sheet.');
    check(c, 'Income & Expenditure FY 2026 still reports the year result (= closing preview net, closing journals excluded by design)', money(net) === surplusPreview, { net, surplusPreview, rows: c.evidence.incomeExpenditure });
    await go(admin, closingLink);
    const afterClose = await ev(admin, () => ({ blockers: $$('.alert-warning li, .alert-warning').map(txt), branches: $$('h3.section-title').length }));
    c.evidence.closingPageAfter = afterClose;
    check(c, 'Closing page: no income or expenditure balance remains for FY 2026', afterClose.blockers.some((b) => /no income or expenditure balance remains/.test(b)), afterClose);
    const bs = await statement(acc, '/statements/balance-sheet?as_of=2026-12-31');
    c.evidence.balanceSheet = bs.rows.filter((r) => /^3|31102|Accumulated|not yet closed|Total/.test(r.join(' ')));
    const bsSurplus = money(bs.rows.find((r) => /^31102 /.test(r[0]))?.[1]);
    const unclosed = money(bs.rows.find((r) => /not yet closed/.test(r[0]))?.[1] ?? '0');
    check(c, 'Balance Sheet carries the year result in 31102 UAT Accumulated Surplus; nothing left "not yet closed"', bsSurplus != null && Math.abs(bsSurplus - surplusPreview) < 0.01 && unclosed === 0, { bsSurplus, surplusPreview, unclosed, rows: c.evidence.balanceSheet });
    const tb26 = await trialBalance(acc, '2026', '2026-12-31');
    c.evidence.tb2026 = tb26.foot;
    check(c, 'Trial Balance FY 2026 still balanced after closing', tb26.foot && tb26.foot[1] === tb26.foot[2], tb26.foot);

    step(c, 'Create FY 2027 via the UI, open it; Trial Balance FY 2027 carries the balance-sheet balances');
    await go(admin, '/fiscal-years/create');
    await act(admin, () => { const f = formByAction('/fiscal-years$'); fill(f, { name: 'FY 2027', start_date: '2027-01-01', end_date: '2027-12-31' }); submitForm(f, 'Save fiscal year'); });
    const fy27 = await info(admin);
    check(c, 'FY 2027 created with monthly periods', /fiscal-years\/\d+/.test(fy27.url) && fy27.alerts.some((a) => /created/i.test(a)), [fy27.url, ...fy27.alerts]);
    if (await ev(admin, () => !!buttonForm('Open year'))) await act(admin, () => submitForm(buttonForm('Open year'), 'Open year'));
    const tb27 = await trialBalance(acc, '2027', '2027-01-31');
    const balanceOf = (tb, code) => tb.rows.find((r) => r[0] === code)?.slice(3, 5).join('/');
    c.evidence.tb2027 = { foot: tb27.foot, alerts: tb27.alerts, sample: tb27.rows.slice(0, 20) };
    c.evidence.tb2027Screenshot = await shot(acc, 'rc-13-tb-2027');
    const bsCodes = ['11101', '11201', '21101', '31102'];
    check(c, 'FY 2027 TB: same balances as FY 2026 closing for 11101, 11201, 21101, 31102; no income/expense rows', bsCodes.every((code) => balanceOf(tb27, code) && balanceOf(tb27, code) === balanceOf(tb26, code)) && !tb27.rows.some((r) => /^(4|5)\d{4}$/.test(r[0] ?? '') && (money(r[3]) !== 0 || money(r[4]) !== 0)), Object.fromEntries(bsCodes.map((code) => [code, { fy2026: balanceOf(tb26, code), fy2027: balanceOf(tb27, code) }])));
    check(c, 'FY 2027 TB balanced', tb27.foot && tb27.foot[1] === tb27.foot[2], tb27.foot);
});

// ---------------------------------------------------------------- summary
rmSync(EXTRA, { force: true });
results.finishedAt = new Date().toISOString();
results.summary = Object.fromEntries(['PASS', 'FAIL', 'BLOCKED', 'NOT RUN'].map((s) => [s, results.cases.filter((x) => x.status === s).map((x) => x.id)]));
results.checks = { total: results.cases.reduce((n, x) => n + x.checks.length, 0), failed: results.cases.reduce((n, x) => n + x.checks.filter((k) => !k.ok).length, 0) };
kit.save();
console.log('\nSummary', JSON.stringify(results.summary), JSON.stringify(results.checks));
console.log('Console errors:', results.consoleErrors.length, 'Defects:', results.defects.length);
await browser.close();
